const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Punjab and Haryana using GAUL administrative boundaries
  var gaul = ee.FeatureCollection("FAO/GAUL/2015/level1");
  var punjab = gaul.filter(ee.Filter.eq('ADM1_NAME', 'Punjab'));
  var haryana = gaul.filter(ee.Filter.eq('ADM1_NAME', 'Haryana'));
  var region = punjab.merge(haryana).geometry();

  // 2. Define time periods: November 2022 and November 2024
  var nov2022_start = ee.Date('2022-11-01');
  var nov2022_end = ee.Date('2022-12-01');
  var nov2024_start = ee.Date('2024-11-01');
  var nov2024_end = ee.Date('2024-12-01');

  // 3. Function to process a given date range
  function processPeriod(startDate, endDate, periodName) {
    var collection = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
                      .filterBounds(region)
                      .filterDate(startDate, endDate);

    var count = collection.size();
    print(periodName + ' Images:', count.getInfo());

    // If collection is empty, return null
    if (count.getInfo() === 0) {
      return null;
    }

    // Map over collection to count fire pixels per image
    var fireCounts = collection.map(function(image) {
      // Create binary mask for fire pixels (fire_mask >= 5)
      var fireMask = image.select('fire_mask');
      var fireBinary = fireMask.gte(5).and(fireMask.lte(7)); // Values 5,6,7 are fires
      // Count fire pixels in region
      var countFire = fireBinary.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      });
      // Also count valid observations (fire_mask != 0) to check data availability
      var validObs = fireMask.neq(0).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      });
      return ee.Feature(null, {
        fireCount: countFire.get('fire_mask'),
        validObs: validObs.get('fire_mask')
      });
    });

    // Aggregate total fire count and valid observations
    var totalFire = fireCounts.aggregate_sum('fireCount');
    var totalValid = fireCounts.aggregate_sum('validObs');

    return {
      totalFire: totalFire,
      totalValid: totalValid
    };
  }

  // 4. Process both periods
  var result2022 = processPeriod(nov2022_start, nov2022_end, '2022');
  var result2024 = processPeriod(nov2024_start, nov2024_end, '2024');

  // 5. Check for missing data (C1)
  if (result2022 === null || result2024 === null) {
    print('One or both periods have no images.');
    print('<answer>C1</answer>');
    return;
  }

  // Get the values
  var fire2022 = result2022.totalFire.getInfo();
  var valid2022 = result2022.totalValid.getInfo();
  var fire2024 = result2024.totalFire.getInfo();
  var valid2024 = result2024.totalValid.getInfo();

  // 6. Check for no valid pixels (C2)
  if (valid2022 === 0 || valid2024 === 0) {
    print('No valid pixels in one or both periods.');
    print('2022 Valid pixels:', valid2022, 'Fire count:', fire2022);
    print('2024 Valid pixels:', valid2024, 'Fire count:', fire2024);
    print('<answer>C2</answer>');
    return;
  }

  // 7. Validate results are numbers (not None/NaN)
  if (fire2022 === null || fire2024 === null || 
      isNaN(fire2022) || isNaN(fire2024)) {
    print('Calculation failed (null/NaN).');
    print('<answer>C3</answer>');
    return;
  }

  // 8. Print evidence
  print('2022 Fire Count:', fire2022, 'Valid pixels:', valid2022);
  print('2024 Fire Count:', fire2024, 'Valid pixels:', valid2024);

  // 9. Compare and output final answer
  if (fire2024 < fire2022) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
